return ['domain'=>'zinn-reseller','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'hr','project-id-version'=>'zinn-reseller','pot-creation-date'=>'2026-10-02T02:25:56+00:00','po-revision-date'=>'2026-10-02T02:25:56+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Reseller Toolkit'=>'Zinn® Reseller Toolkit','https://zinndigital.com/wordpress-plugins/zinn-reseller'=>'https://zinndigital.com/wordpress-plugins/zinn-reseller','Sell Zinn Digital® hosting from your own WordPress site — WordPress, WooCommerce, agency, reseller, cloud and VPS hosting. Search and offer domains from your reseller account, sign your clients straight into their hosting panel, and provision hosting automatically when a WooCommerce order is paid.'=>'Prodajte Zinn Digital® hosting sa svoje vlastite WordPress stranice — WordPress, WooCommerce, agencijski, preprodavački, cloud i VPS hosting. Pretražujte i nudite domene sa svog računa za preprodavače, prijavite svoje klijente izravno u njihov hosting panel i automatski dodijelite hosting kada je WooCommerce narudžba plaćena.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','The hosting platform answered with status %d.'=>'Platforma za hosting odgovorila je sa statusom %d.','Find your domain name'=>'Pronađite naziv svoje domene','Search'=>'Pretraži','No extensions were checked for that name.'=>'Nijedno proširenje nije provjereno za taj naziv.','Domain search is unavailable on this site at the moment.'=>'Pretraživanje domena trenutno nije dostupno na ovom web-mjestu.','We could not reach the domain registry just now. Please try again in a moment.'=>'Trenutačno nismo mogli pristupiti registru domena. Molimo pokušajte ponovno za trenutak.','The API key is missing or no longer valid. Check it under Zinn Digital® → Reseller Toolkit.'=>'API ključ nedostaje ili više nije valjan. Provjerite ga pod Zinn Digital® → Reseller Toolkit.','This API key does not carry the sites.view permission, which the domain search needs. Add it to the key in your reseller panel, or clear the key here to fall back to the public search.'=>'Ovaj API ključ nema dopuštenje sites.view, koje je potrebno za pretraživanje domena. Dodajte ga ključu na svojoj ploči za preprodavače ili izbrišite ključ ovdje kako biste se vratili na javno pretraživanje.','Only administrators see this:'=>'Samo administratori vide ovo:','We could not check this one — try again'=>'Nismo uspjeli provjeriti ovo — pokušajte ponovo','Already registered'=>'Već registrirani','Available — ask us for a price'=>'Dostupno — zatražite cijenu od nas','Available — %1$s %2$s for the first year'=>'Dostupno — %1$s %2$s za prvu godinu','Register it'=>'Registrirajte ga','Manage my hosting'=>'Upravljajte mojim hostingom','Please sign in first.'=>'Molimo prvo se prijavite.','This account is not linked to a hosting service yet.'=>'Ovaj račun još nije povezan s uslugom hostinga.','The hosting platform did not return a sign-in link.'=>'Platforma za smještaj web-stranica nije vratila poveznicu za prijavu.','Reseller Toolkit'=>'Alati za preprodavače','Account'=>'Račun','Features'=>'Značajke','Styling'=>'Stiliziranje','AI agents (MCP)'=>'AI agenti (MCP)','Allow AI agents (MCP)'=>'Dozvoli AI agente (MCP)','Off: the tools below and their REST routes are not registered at all.'=>'Isključeno: alati u nastavku i njihove REST rute uopće nisu registrirani.','Your Zinn Digital® reseller account'=>'Vaš Zinn Digital® preprodavački račun','Create a reseller API key in your Zinn® dashboard under Developer → API keys, and paste it here.'=>'Stvorite API ključ preprodavača na svojoj nadzornoj ploči Zinn® pod Razvojni programer → API ključevi i zalijepite ga ovdje.','Reseller API key'=>'API ključ preprodavača','Held on this site only, and never included in an export or a diagnostics report.'=>'Pohranjeno samo na ovom web-mjestu i nikada nije uključeno u izvoz ili dijagnostički izvještaj.','Plan to provision'=>'Paket za dodjelu','The plan code new customers are put on. Leave blank to be asked each time.'=>'Kod plana na koji se dodjeljuju novi korisnici. Ostavite prazno ako želite da vas se svaki put pita.','API address'=>'API adresa','Leave this alone unless Zinn® support has asked you to change it.'=>'Ostavite ovo kako jest, osim ako vam podrška za Zinn® nije zatražila da to promijenite.','Control-panel address'=>'Adresa upravljačke ploče','Where the “My hosting” link sends your customers.'=>'Kamo poveznica „Moj smještaj” šalje vaše klijente.','Domain search'=>'Pretraživanje domena','Provide the [zinn_domain_search] shortcode'=>'Navedite kratki kôd [zinn_domain_search]','Put the shortcode on any page to let visitors check a domain and buy it through you.'=>'Postavite kratki kôd na bilo koju stranicu kako biste posjetiteljima omogućili provjeru domene i njezinu kupnju putem vas.','Panel link'=>'Poveznica ploče','Show a “My hosting” link to signed-in customers'=>'Prikaži poveznicu „Moj hosting” prijavljenim korisnicima','WooCommerce provisioning'=>'Pružanje usluge WooCommerce','Provision hosting automatically when a WooCommerce order completes'=>'Automatski dodijelite hosting kada se narudžba u WooCommerceu dovrši','Only takes effect on orders containing a product you have mapped to a Zinn® plan.'=>'Primjenjuje se samo na narudžbe koje sadrže proizvod koji ste mapirali na Zinn® paket.','Domain search appearance'=>'Izgled pretraživanja domene','This widget renders inside your own theme. Pick a preset, or set your own colours — either way nothing is added to your pages that a visitor can see as ours.'=>'Ovaj se widget prikazuje unutar vaše vlastite teme. Odaberite predložak ili postavite vlastite boje — u svakom slučaju na vaše se stranice ne dodaje ništa što bi posjetitelj mogao prepoznati kao naše.','Every class the widget uses is listed in the plugin’s readme, so a developer can override anything a preset does not cover.'=>'Svaka klasa koju widget koristi navedena je u datoteci readme dodatka, tako da razvojni programer može nadjačati sve što unaprijed postavljena postavka ne pokriva.','Follow my theme'=>'Pratite moju temu','Soft'=>'Meko','High contrast'=>'Visoki kontrast','Compact'=>'Kompaktno','Buy-link colour'=>'Boja poveznice za kupnju','“Available” colour'=>'Boja za „Dostupno”','“Could not check” colour'=>'Boja za „Nije uspjela provjera”','Error colour'=>'Boja pogreške','Corner rounding'=>'Zaobljenje kuteva','Space inside each row'=>'Razmak unutar svakog retka','Text size'=>'Veličina teksta','Domain-name weight'=>'Težina naziva domene','No reseller API key yet.'=>'Još nema API ključa za preprodavača.','Domain search already works without one, at the public prices. The panel link and WooCommerce provisioning need a key: create one in your Zinn® dashboard under Developer → API keys.'=>'Pretraživanje domena već radi bez ključa, po javnim cijenama. Poveznica na upravljačku ploču i omogućavanje za WooCommerce zahtijevaju ključ: izradite ga na svojoj Zinn® nadzornoj ploči pod Developer → API keys.','Open my Zinn® dashboard'=>'Otvorite moju Zinn® upravljačku ploču','A key is set, but nothing is switched on.'=>'Ključ je postavljen, ali ništa nije uključeno.','None of the three features is enabled, so this plugin is doing nothing on your site. Turn on what you need under Features.'=>'Nijedna od triju značajki nije omogućena, pa ovaj priključak ne radi ništa na vašem web-mjestu. Uključite ono što vam je potrebno pod Značajke.','Open Features'=>'Otvori značajke','Ready — %d feature switched on.'=>'Spremno — %d značajka uključena.' . "\0" . 'Spremno — uključeno %d značajki.' . "\0" . 'Spremno — uključeno %d značajki.','Selling from'=>'Prodaja od','Settings'=>'Postavke','No API key yet, so nothing is connected.'=>'Još nema API ključa, pa ništa nije povezano.','Not connected: %s'=>'Nije povezano: %s','Connected. Your reseller programme is %s.'=>'Povezano. Vaš partnerski program za preprodavače je %s.','No Zinn® API key is configured, so nothing was provisioned.'=>'Nije konfiguriran nijedan Zinn® API ključ, pa ništa nije pripremljeno.','This order did not include a domain name, so there was nothing to provision.'=>'Ova narudžba nije uključivala naziv domene, stoga nije bilo ničega za konfiguriranje.','The hosting platform did not return a site.'=>'Hosting platforma nije vratila web-mjesto.','Zinn® hosting provisioned for %1$s (service %2$s).'=>'Zinn® hosting omogućen za %1$s (usluga %2$s).','The hosting platform did not return a client account.'=>'Hosting platforma nije vratila korisnički račun.','Zinn® hosting was NOT provisioned: %s'=>'Zinn® hosting NIJE dodijeljen: %s','Zinn® product line'=>'Linija proizvoda Zinn®','The Zinn® product line to provision when this product is bought. Leave blank to use the default from the plugin settings.'=>'Linija proizvoda Zinn® koju treba isporučiti kada se ovaj proizvod kupi. Ostavite prazno kako biste upotrijebili zadano iz postavki priključka.','Zinn® hosting'=>'Zinn® hosting','Service id'=>'ID usluge','Nothing provisioned for this order.'=>'Ništa nije dodijeljeno za ovu narudžbu.','Stored. Type a new value to replace it.'=>'Spremljeno. Upišite novu vrijednost kako biste je zamijenili.','Filter this list…'=>'Filtrirajte ovaj popis…','Filter this list'=>'Filtrirajte ovaj popis','Nothing matches that filter.'=>'Ništa ne odgovara tom filtru.','Add a row'=>'Dodaj redak','Remove this row'=>'Uklonite ovaj redak','Remove'=>'Ukloni','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — pregled','Overview'=>'Pregled','Copied'=>'Kopirano','Every Zinn® plugin on this site, and whether it is working.'=>'Svaki Zinn® priključak na ovoj web-stranici i radi li.','No connection is needed for this plugin.'=>'Za ovaj priključak nije potrebno povezivanje.','Open settings'=>'Otvori postavke','You do not have permission to change these settings.'=>'Nemate dopuštenje za promjenu ovih postavki.','Settings sections'=>'Odjeljci postavki','Support'=>'Podrška','Save changes'=>'Spremi promjene','Tools'=>'Alati','Export settings'=>'Izvoz postavki','Reset to defaults'=>'Vrati na zadano','This puts every setting on this plugin back to its default. Continue?'=>'Ovo vraća sve postavke ovog priključka na njihove zadane vrijednosti. Želite li nastaviti?','Diagnostics for support'=>'Dijagnostika za podršku','Import a settings file'=>'Uvezite datoteku postavki','Import'=>'Uvezi','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Izvezene datoteke nikada ne sadrže lozinke, tokene ili API ključeve — morat ćete ih ponovno unijeti na novom web-mjestu.','Settings saved.'=>'Postavke su spremljene.','Every setting on this plugin is back to its default.'=>'Sve postavke ovog priključka vraćene su na zadane vrijednosti.','Done.'=>'Dovršeno.','That action is not available.'=>'Ta radnja nije dostupna.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Tu datoteku nije bilo moguće pročitati. Odaberite datoteku postavki izvezenu iz Zinn® priključka.','That file is too large to be a settings export.'=>'Ta je datoteka prevelika da bi bila izvoz postavki.','That file is not a Zinn® settings export.'=>'Ta datoteka nije izvoz postavki za Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Ta je datoteka izvezena iz drugog priključka (%s), pa bi se njezinim uvozom ovdje spremile postavke koje ovaj priključak ne razumije.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d postavka je uvezena. Lozinke i API ključevi nikada se ne nalaze u izvozu, stoga ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Lozinke i API ključevi nikada se ne nalaze u izvozu, pa ih unesite ponovno.' . "\0" . 'Uvezeno je %d postavki. Lozinke i API ključevi nikada se ne nalaze u izvozu, pa ih unesite ponovno.','Connected'=>'Povezano','Connecting…'=>'Povezivanje…','Connected, but something needs attention'=>'Povezano, ali nešto zahtijeva pažnju','Not connected'=>'Nije povezano','Running on your own account'=>'Izvodi se na vašem vlastitom računu','We could not check this'=>'Nismo mogli ovo provjeriti','This plugin did not say why. Send a diagnostics report and we will look.'=>'Ovaj dodatak nije naveo razlog. Pošaljite dijagnostičko izvješće i mi ćemo pogledati.','Connection status'=>'Status veze','Last checked %s ago.'=>'Zadnja provjera prije %s.','(opens in a new tab)'=>'(otvara se u novoj kartici)','Send this to Zinn® support'=>'Pošaljite ovo podršci za Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Upravo to će biti poslano — ništa drugo i ništa skriveno. Vaše lozinke, tokeni i API ključevi nisu u tome.','The diagnostics report that will be sent'=>'Dijagnostički izvještaj koji će biti poslan','Copy to clipboard'=>'Kopiraj u međuspremnik','Send this report to Zinn® support'=>'Pošaljite ovo izvješće podršci za Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otvaramo tiket za podršku za Vas i odgovaramo e-poštom. Ako ga radije ne biste poslali, kopirajte ga iznad i sami ga zalijepite u tiket.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Nismo uspjeli doći do Zinn Digital® s ovog poslužitelja (%s). Kopirajte gore navedeni izvještaj i umjesto toga otvorite upit za podršku — nema pogreške u vašim postavkama.','Sent. Zinn® support has your report and will reply by email.'=>'Poslano. Podrška za Zinn® zaprimila je Vašu prijavu i odgovorit će e-poštom.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Poslano. Podrška za Zinn® zaprimila je vašu prijavu — referenca %s — i odgovorit će vam putem e-pošte.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Poslali ste nekoliko izvještaja u kratkom vremenu. Pričekajte nekoliko minuta i pokušajte ponovno — prethodni su stigli.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® trenutačno nije mogao prihvatiti izvještaj — problem je s naše strane, a ne s Vaše. Pokušajte ponovno uskoro ili kopirajte gornji izvještaj u prijavu.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Izvještaj je odbijen (HTTP %d). Kopirajte ga iznad i otvorite prijavu, navodeći taj broj.','%s — guides and services'=>'%s — vodiči i usluge','User guides'=>'Korisnički priručnici','Read the %s user guide'=>'Pročitajte korisnički vodič za %s','Hide this'=>'Sakrij ovo','Zinn® hosting for WordPress'=>'Zinn® hosting za WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, svakodnevne sigurnosne kopije, besplatna migracija i upravljačka ploča stvorena za osobe koje vode više od jedne web-stranice.','The Zinn® marketplace'=>'Tržnica Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte i prodajte etablirane web stranice, domene i plasmane poveznica, pri čemu se novac sigurno čuva dok obje strane ne budu zadovoljne.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — zaposlite ljude kojima je to posao','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naša globalna burza slobodnih zanimanja: pregledajte više od 10 000 gotovih usluga pisaca, dizajnera, programera i SEO stručnjaka ili objavite projekt i omogućite im davanje ponuda.','Style preset'=>'Zadana postavka stila','A starting point. Anything below overrides it.'=>'Početna točka. Sve ispod je nadjačava.','Use my own colours and sizes'=>'Upotrijebite moje vlastite boje i veličine','Leave this off and the preset is used exactly as it is.'=>'Ostavite ovo isključeno i predložak će se koristiti točno onakav kakav jest.','See the Zinn Digital® release notes.'=>'Pogledajte bilješke o izdanju za Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Usluga ažuriranja Zinn® nije izdala poveznicu za preuzimanje ovog ažuriranja. Provjerite može li ovo web-mjesto pristupiti platformi Zinn®, a zatim pokušajte ponovno.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Ažuriranje se nije moglo preuzeti s usluge ažuriranja Zinn® (%s). Pokušajte ponovo za nekoliko minuta.','The downloaded update failed its integrity check and was not installed.'=>'Preuzeto ažuriranje nije prošlo provjeru integriteta i nije instalirano.','The action could not be completed. Try again, and if it keeps failing, contact the site administrator.'=>'Radnja se nije mogla dovršiti. Pokušajte ponovno, a ako se problem nastavi, obratite se administratoru web-mjesta.','Connect an AI app'=>'Povežite AI aplikaciju','This connection request has expired. Go back to the app and start connecting again.'=>'Ovaj zahtjev za povezivanje je istekao. Vratite se u aplikaciju i ponovno započnite povezivanje.','%1$s is asking to use %2$s on this site as %3$s. It can do only what your WordPress account is allowed to do, and you can disconnect it at any time from the AI agents (MCP) settings.'=>'%1$s traži korištenje %2$s na ovom web-mjestu kao %3$s. Može raditi samo ono što vaš WordPress račun smije raditi, a možete ga prekinuti u bilo kojem trenutku u postavkama AI agenata (MCP).','%1$s identified itself from %2$s.'=>'%1$s se identificirao s %2$s.','%1$s registered itself automatically. Only continue if you started this from %2$s.'=>'%1$s se automatski registrirao. Nastavite samo ako ste ovo pokrenuli s %2$s.','Your account cannot use these tools on this site. Ask an administrator.'=>'Vaš račun ne može koristiti ove alate na ovoj web-stranici. Obratite se administratoru.','After you answer you will go back to %s.'=>'Nakon što odgovorite, vratit ćete se na %s.','Allow %s'=>'Dopusti %s','Do not allow'=>'Nemojte dopustiti','A required value is missing or has the wrong form. Check the ability\'s input schema.'=>'Potrebna vrijednost nedostaje ili je u pogrešnom obliku. Provjerite ulaznu shemu (input schema) mogućnosti.','The site refused the request.'=>'Web-mjesto je odbilo zahtjev.','Let AI assistants such as Claude, Cursor or VS Code work on this site for you through MCP (Model Context Protocol). They sign in as a WordPress user (Claude and ChatGPT by approving them here, others with an application password) and can do only what that user is allowed to do.'=>'Dopustite AI asistentima kao što su Claude, Cursor ili VS Code da rade na ovom web-mjestu za vas putem MCP-a (Model Context Protocol). Prijavljuju se kao WordPress korisnik (Claude i ChatGPT odobravanjem ovdje, drugi pomoću lozinke aplikacije) i mogu raditi samo ono što je tom korisniku dopušteno.','AI agents need WordPress 6.9 or later. Update WordPress to use them.'=>'AI agenti zahtijevaju WordPress 6.9 ili noviji. Ažurirajte WordPress kako biste ih koristili.','Connection address (MCP endpoint)'=>'Adresa za povezivanje (krajnja točka MCP-a)','Claude and ChatGPT: sign in instead'=>'Claude i ChatGPT: umjesto toga se prijavite','Add the connection address as a custom connector in Claude, or as an app in ChatGPT developer mode. They open this site so you can approve them; no password to copy.'=>'Dodajte adresu veze kao prilagođeni poveznik u Claudeu ili kao aplikaciju u razvojnom načinu za ChatGPT. Oni otvaraju ovo web-mjesto kako biste ih mogli odobriti; nema lozinke za kopiranje.','AI apps connected to your account:'=>'AI aplikacije povezane s Vašim računom:','Disconnect'=>'Prekini vezu','Other AI apps: an application password'=>'Druge AI aplikacije: lozinka aplikacije','Create an application password for your user'=>'Stvorite lozinku aplikacije za svog korisnika','Add this to your AI app’s MCP settings, with your username and that password:'=>'Dodajte ovo u MCP postavke svoje AI aplikacije, s vašim korisničkim imenom i tom lozinkom:','VS Code: put the same entry under "servers" in .vscode/mcp.json, not under "mcpServers".'=>'VS Code: stavite isti unos pod "servers" u .vscode/mcp.json, a ne pod "mcpServers".','Tools an AI agent can use here (%d):'=>'Alati koje AI agent ovdje može koristiti (%d):','User guide: AI agents and MCP'=>'Korisnički priručnik: AI agenti i MCP','Developer docs: abilities, REST and MCP'=>'Dokumentacija za razvojne programere: mogućnosti, REST i MCP','Manage your hosting clients, their plans and their sites on Zinn Digital® from this site.'=>'Upravljajte svojim klijentima za hosting, njihovim paketima i njihovim web-mjestima na Zinn Digital® s ovog web-mjesta.','Your clients, their plans and their sites, through your Zinn Digital® reseller account.'=>'Vaši klijenti, njihovi paketi i njihove web stranice, putem Vašeg Zinn Digital® preprodajnog računa.','Read your reseller account'=>'Pročitajte svoj preprodavački račun','Returns your reseller account in one read: brand, plans, clients and services counts, and what is set up.'=>'Vraća vaš račun preprodavača u jednom čitanju: marku, planove, broj klijenata i usluga te što je postavljeno.','List your clients'=>'Navedite svoje klijente','Lists your client accounts, a page at a time (cursor, limit).'=>'Prikazuje Vaše korisničke račune klijenata, stranicu po stranicu (cursor, limit).','Create a client'=>'Stvorite klijenta','Creates a client account under yours (name; default_currency, a three-letter code). Put them on a plan before their first site.'=>'Stvara klijentski račun pod vašim (name; default_currency, troznamenkasti kôd). Dodijelite im plan prije njihove prve web-stranice.','Read a client\'s plan'=>'Pročitajte plan klijenta','Returns which plan a client is on and what it costs you (client_id).'=>'Vraća na kojem je paketu klijent i koliko vas to košta (client_id).','Put a client on a plan'=>'Dodijelite klijenta planu','Puts a client on one of your plans (client_id, plan_code; interval: month or year). Do this before their first site.'=>'Dodjeljuje klijenta jednom od vaših planova (client_id, plan_code; interval: month ili year). Učinite to prije njihove prve web-stranice.','List the plans you can sell'=>'Navedite pakete koje možete prodavati','Lists the hosting plans and their prices (product_line and currency narrow it).'=>'Prikazuje popis planova smještaja i njihove cijene (product_line i currency ga sužavaju).','List your clients\' sites'=>'Popišite web-mjesta svojih klijenata','Lists everything you have provisioned for your clients (client_id and status narrow it), a page at a time.'=>'Prikazuje popis svega što ste pripremili za svoje klijente (client_id i status sužavaju odabir), stranicu po stranicu.','Create a site for a client'=>'Stvorite web-mjesto za klijenta','Creates a hosted site for one of your clients (client_id, product_line, primary_domain). It is billed to your account at the client\'s plan, as from your shop.'=>'Stvara hostiranu web-stranicu za jednog od vaših klijenata (client_id, product_line, primary_domain). Naplaćuje se na vaš račun prema klijentovom planu, kao iz vaše trgovine.','Suspend a client\'s site'=>'Obustavite klijentovu web-stranicu','Puts a client\'s site on a non-payment hold (site_id; reason: your own note, never shown to the client). The site stops serving until it is unsuspended.'=>'Stavlja web-mjesto klijenta na čekanje zbog neplaćanja (site_id; reason: Vaša vlastita bilješka, nikada se ne prikazuje klijentu). Web-mjesto prestaje s radom dok mu se ne ukine suspenzija.','Unsuspend a client\'s site'=>'Ukinite suspenziju klijentove web-stranice','Lifts a non-payment hold, so the site serves again (site_id).'=>'Uklanja suspenziju zbog neplaćanja, tako da web-mjesto ponovno radi (site_id).','Read the Reseller Toolkit settings'=>'Pročitajte postavke alata za preprodavače','Returns this plugin\'s settings (the API address, the plan new orders use, which features are on). The API key is never returned, only whether one is saved.'=>'Vraća postavke ovog priključka (adresu API-ja, paket koji koriste nove narudžbe, koje su značajke uključene). API ključ se nikada ne vraća, samo podatak je li spremljen.','Change the Reseller Toolkit settings'=>'Promijenite postavke Reseller Toolkita','Changes the settings you send (plan_code, enable_domain_search, enable_panel_link, enable_woocommerce) and keeps the rest. The API key and address are changed on the screen only.'=>'Mijenja postavke koje pošaljete (plan_code, enable_domain_search, enable_panel_link, enable_woocommerce) i zadržava ostale. API ključ i adresa mijenjaju se samo na zaslonu.','Add your Zinn Digital® reseller API key on the Reseller Toolkit screen first.'=>'Prvo dodajte svoj Zinn Digital® API ključ preprodavača na zaslonu Reseller Toolkit.']];